(function ($) {
                    "use strict";    
                    $(document).ready(function () {
                        ///============= Nav Menu Sidebar Popup  =============\\\
                        $(".nav_menu_popup-990 .nav_menu_bar i").on("click", function () {
                            $(".nav_menu_popup-990 .nav_menu_bar-popup").addClass("show");
                        });
                        $(".nav_menu_popup-990 .nav_menu_bar-popup-close").on("click", function () {
                            $(".nav_menu_popup-990 .nav_menu_bar-popup").removeClass("show");
                        });	
                        ///============= * Responsive Menu Toggle  =============\\\
                        var mobileItems = jQuery('.vertical_menu-990');
                        mobileItems.find('ul li.menu-item-has-children, ul li.mega-menu-enabled').append('<span class="mobile-arrows far fa-plus"></span>');

                        jQuery(".vertical_menu-990 .mobile-arrows").click(function() {
                            jQuery(this).parent().find('ul.sub-menu:first, .mega-menu-wrap').slideToggle(300);
                            jQuery(this).parent().find('> .mobile-arrows").toggleClass('is-open');
                        });
                        // ///============= * MegaMenu Width  =============\\\
                        function setMegaMenuStyles() {
                            var windowWidth = $(window).width();                            
                            if (windowWidth >= 1000) {
                                $('.header_mega-menu .mega-menu-wrap').each(function() {
                                    var leftPosition = Math.floor($(this).position().left - $(this).offset().left);
                                    $(this).css({
                                        'width': windowWidth + 'px',
                                        'left': leftPosition + 'px'
                                    }); 
                                });
                            } else {
                                $('.header_mega-menu .mega-menu-wrap').each(function() {
                                    $(this).css({
                                        'width': '',
                                        'left': ''
                                    });
                                });
                            }
                        }
                        $(document).ready(function() {
                            setMegaMenuStyles();
                            $(window).resize(function() {
                                setMegaMenuStyles();
                            });
                        });
                    });
                })(jQuery);

const lazyloadRunObserver = () => {
					const lazyloadBackgrounds = document.querySelectorAll( `.e-con.e-parent:not(.e-lazyloaded)` );
					const lazyloadBackgroundObserver = new IntersectionObserver( ( entries ) => {
						entries.forEach( ( entry ) => {
							if ( entry.isIntersecting ) {
								let lazyloadBackground = entry.target;
								if( lazyloadBackground ) {
									lazyloadBackground.classList.add( 'e-lazyloaded' );
								}
								lazyloadBackgroundObserver.unobserve( entry.target );
							}
						});
					}, { rootMargin: '200px 0px 200px 0px' } );
					lazyloadBackgrounds.forEach( ( lazyloadBackground ) => {
						lazyloadBackgroundObserver.observe( lazyloadBackground );
					} );
				};
				const events = [
					'DOMContentLoaded',
					'elementor/lazyload/observe',
				];
				events.forEach( ( event ) => {
					document.addEventListener( event, lazyloadRunObserver );
				} );

